/* Interface language. Strings live in _locales/<lang>/messages.json (generated by
   tools/build-locales.py). The language follows the browser unless the user picks one in
   settings (storage key uiLanguage). GPL-3.0-or-later. */
globalThis.I18N=(()=>{
  const LANGS=['zh_TW','zh_CN','en'];
  const HTML_LANG={zh_TW:'zh-Hant',zh_CN:'zh-Hans',en:'en'};
  let table={},current='zh_TW';
  function browserLanguage(){
    const ui=(chrome.i18n?.getUILanguage?.() || navigator.language || 'en').toLowerCase();
    if(/^zh-(tw|hk|mo|hant)/.test(ui))return 'zh_TW';
    if(ui.startsWith('zh'))return 'zh_CN';
    return 'en';
  }
  async function load(){
    let choice='auto';
    try{choice=(await chrome.storage.local.get('uiLanguage')).uiLanguage || 'auto';}catch{}
    current=LANGS.includes(choice)?choice:browserLanguage();
    try{table=await fetch(chrome.runtime.getURL(`_locales/${current}/messages.json`)).then(r=>r.json());}catch{table={};}
    return current;
  }
  let ready=load();
  // t('key', a, b) fills $1, $2 … in the message.
  function t(key,...subs){const message=table[key]?.message;if(message==null)return key;return message.replace(/\$(\d)/g,(_,n)=>subs[n-1]==null?'':String(subs[n-1]));}
  function markup(text){
    const nodes=[];
    for(const part of text.split(/(<code>.*?<\/code>|<strong>.*?<\/strong>|<br>)/)){
      const tag=part.match(/^<(code|strong)>(.*)<\/\1>$/);
      if(tag){const node=document.createElement(tag[1]);node.textContent=tag[2];nodes.push(node);}
      else if(part==='<br>')nodes.push(document.createElement('br'));
      else if(part)nodes.push(document.createTextNode(part));
    }
    return nodes;
  }
  function apply(root=document){
    if(root===document)document.documentElement.lang=HTML_LANG[current];
    for(const element of root.querySelectorAll('[data-i18n]'))element.textContent=t(element.dataset.i18n);
    // A few bundled messages carry <code>, <strong> or <br>; build them as nodes, never as HTML.
    for(const element of root.querySelectorAll('[data-i18n-html]'))element.replaceChildren(...markup(t(element.dataset.i18nHtml)));
    for(const attribute of ['placeholder','title','aria-label','data-empty'])for(const element of root.querySelectorAll(`[data-i18n-${attribute}]`))element.setAttribute(attribute,t(element.getAttribute(`data-i18n-${attribute}`)));
  }
  function reload(){ready=load();return ready;}
  return {LANGS,t,apply,reload,get ready(){return ready;},get current(){return current;}};
})();
